def load_globs():
    """Load all grids from the current session"""
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}

    sessions_file = os.path.join(d, '..', '..', 'sessions', os.path.basename(d) + '.jsonl')
    sessions_file = os.path.normpath(sessions_file)

    if not os.path.exists(sessions_file):
        # Try alternative path
        base = d
        sessions_file = os.path.join(base, 'sessions', os.path.basename(base) + '.jsonl')

    G = {}
    if os.path.exists(sessions_file):
        t = open(sessions_file).read().replace('\\\\n', '\n')
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t, re.MULTILINE):
            k = m.group(1)
            h, w = int(m.group(2)), int(m.group(3))
            # Find the next h rows after m.end()
            content = t[m.end():m.end() + h * 16]  # rough estimate per row
            if 'Final input:\n' in t[m.end():]:
                break
            rows = content.split('\n')[:min(h, len(rows))]
            for r_idx, r in enumerate(rows):
                if r.strip():
                    # Fill empty rows if any
                    while len(rows) < h:
                        break
            try:
                grid = [[int(x) for x in r.split()] for r in rows if r.strip() and 'Final' not in r]
                while len(grid) < h:
                    grid.append([0])
                if len(grid[0]) > 0:
                    G[k] = grid
            except:
                pass

    return G

